PLURALS = {
 "datetime_months_relative": {"one": "%1$d માસ પહેલાં", "other": "%1$d માસ પહેલાં"},
 "datetime_years_relative": {"one": "%1$d વર્ષ પહેલાં", "other": "%1$d વર્ષ પહેલાં"},
}

def esc(s):
    # value is already XML-safe (no raw &,<,> introduced); keep as-is
    return s

with open(TARGET, 'r', encoding='utf-8') as f:
    content = f.read()

applied = []
inserted = []
plurals_done = []
errors = []

# --- 1. Replace / insert string keys ---
for key, val in T.items():
    pat = re.compile(r'(<string name="%s"[^>]*>).*?(</string>)' % re.escape(key), re.DOTALL)
    if pat.search(content):
        content = pat.sub(lambda m: m.group(1) + esc(val) + m.group(2), content, count=1)
        applied.append(key)
    else:
        # new key -> insert before </resources> via rfind
        idx = content.rfind('</resources>')
        if idx == -1:
            errors.append("no </resources>")
            break
        ins = '    <string name="%s">%s</string>\n' % (key, esc(val))
        content = content[:idx] + ins + content[idx:]
        inserted.append(key)

# --- 2. Replace stale plurals ---
for pname, items in PLURALS.items():
    items_xml = ''.join('        <item quantity="%s">%s</item>\n' % (q, t) for q, t in items.items())
    block = '    <plurals name="%s">\n%s    </plurals>' % (pname, items_xml)
    pat = re.compile(r'<plurals name="%s">.*?</plurals>' % re.escape(pname), re.DOTALL)
    if pat.search(content):
        content = pat.sub(lambda m: block, content, count=1)
        plurals_done.append(pname)
    else:
        idx = content.rfind('</resources>')
        content = content[:idx] + block + '\n' + content[idx:]
        plurals_done.append(pname + '(inserted)')

with open(TARGET, 'w', encoding='utf-8', newline='\n') as f:
    f.write(content)

print(json.dumps({
    "applied": applied, "inserted": inserted,
    "plurals_done": plurals_done, "errors": errors
}, ensure_ascii=False))
